class Solution {
public:
    int gcd(int a, int b) {
        while (b) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    int countDifferentSubsequenceGCDs(vector<int>& nums) {
        int maxVal = 0;
        for (int num : nums) {
            if (num > maxVal) {
                maxVal = num;
            }
        }
        vector<bool> present(maxVal + 1, false);
        for (int num : nums) {
            present[num] = true;
        }
        int ans = 0;
        for (int x = 1; x <= maxVal; x++) {
            int g = 0;
            for (int j = x; j <= maxVal; j += x) {
                if (present[j]) {
                    g = gcd(g, j);
                }
            }
            if (g == x) {
                ans++;
            }
        }
        return ans;
    }
};
